class Solution:
    def solve(self, head):
        if not head:
            return head

        even_head = even = ListNode(0)
        odd_head = odd = ListNode(0)

        current = head
        while current:
            if current.val % 2 == 0:
                even.next = current
                even = even.next
            else:
                odd.next = current
                odd = odd.next
            current = current.next

        even.next = odd_head.next
        odd.next = None

        return even_head.next
